import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function Reports() {
  const [results, setResults] = useState([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [totalTeachers, setTotalTeachers] = useState(0);
  const [totalSubjects, setTotalSubjects] = useState(0);
  const [statusFilter, setStatusFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    // 🟢 Backend එකෙන් එන දත්ත අනිවාර්යයෙන්ම Array එකක් නම් පමණක් සෙට් වෙන ලෙස ආරක්ෂා කළා
    axios.get('http://localhost:8082/api/student-results')
      .then(res => {
        if (res.data && Array.isArray(res.data)) {
          setResults(res.data);
        } else {
          setResults([]);
        }
      })
      .catch(() => setResults([]));

    axios.get('http://localhost:8082/api/view-students').then(res => setTotalStudents(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
    axios.get('http://localhost:8082/api/view-teachers').then(res => setTotalTeachers(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
    axios.get('http://localhost:8082/api/view-subjects').then(res => setTotalSubjects(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
  }, []);

  // 🟢 100%ක්ම ආරක්ෂිතව Array එකක් දැයි පරික්ශා කර පෙරීම සිදු කරයි (Crash වෙන්නේම නැත)
  const filteredResults = (results && Array.isArray(results)) 
    ? results.filter(r => {
        const matchesSearch = (r.student_name || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
                              (r.quiz_title || '').toLowerCase().includes(searchQuery.toLowerCase());
        const matchesStatus = statusFilter === 'All' || r.status === statusFilter;
        return matchesSearch && matchesStatus;
      }) 
    : [];

  const handlePrint = () => { window.print(); };

  const handleDownloadPDF = () => {
    const printWindow = window.open('', '_blank');
    let tableRows = '';
    
    filteredResults.forEach((r, index) => {
      const percentage = ((r.marks_obtained / r.total_marks) * 100).toFixed(0);
      tableRows += `
        <tr>
          <td>${index + 1}</td>
          <td style="font-weight: bold;">${r.student_name}</td>
          <td>${r.grade}</td>
          <td>${r.subject_name}</td>
          <td>${r.quiz_title}</td>
          <td>${r.marks_obtained} / ${r.total_marks}</td>
          <td>${percentage}%</td>
          <td style="font-weight: bold; color: ${r.status === 'Pass' ? '#16a34a' : '#dc2626'}">${r.status}</td>
        </tr>
      `;
    });

    const htmlContent = `
      <html>
      <head>
        <title>Student Performance Report - AuraPen Saku</title>
        <style>
          body { font-family: sans-serif; padding: 40px; color: #333; }
          .header { text-align: center; border-bottom: 3px solid #15803d; padding-bottom: 20px; margin-bottom: 30px; }
          .header h1 { margin: 0; color: #15803d; font-size: 28px; }
          .header p { margin: 5px 0 0 0; color: #64748b; font-size: 14px; }
          .meta-info { display: flex; justify-content: space-between; margin-bottom: 30px; font-size: 13px; color: #475569; }
          table { width: 100%; border-collapse: collapse; margin-top: 10px; }
          th, td { border: 1px solid #cbd5e1; padding: 12px 10px; text-align: left; font-size: 13px; }
          th { background-color: #f8fafc; color: #475569; font-weight: bold; }
          .footer-sign { margin-top: 60px; display: flex; justify-content: space-between; }
          .signature { border-top: 1px dashed #333; width: 200px; text-align: center; padding-top: 8px; font-size: 13px; color: #475569; }
        </style>
      </head>
      <body>
        <div class="header">
          <h1>AURAPEN SAKU EDUCATIONAL INSTITUTE</h1>
          <p>Official Student Academic Performance Report Center</p>
        </div>
        <div class="meta-info">
          <div><strong>Report Type:</strong> Examination & Quiz Summary</div>
          <div><strong>Generated Date:</strong> ${new Date().toLocaleDateString()}</div>
        </div>
        <table>
          <thead>
            <tr>
              <th>No.</th>
              <th>Student Name</th>
              <th>Grade</th>
              <th>Subject</th>
              <th>Quiz Title</th>
              <th>Marks</th>
              <th>Percentage</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            ${tableRows || '<tr><td colspan="8" style="text-align:center;">No records found.</td></tr>'}
          </tbody>
        </table>
        <div class="footer-sign">
          <div class="signature">Prepared By</div>
          <div class="signature">Authorized Signature</div>
        </div>
        <script>
          window.onload = function() { window.print(); window.close(); }
        </script>
      </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
  };

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      
      {/* Metrics Summary Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '30px' }}>
        <div style={{...styles.statCard, borderLeft: '6px solid #16a34a'}}><div style={styles.statIcon}>👨‍🎓</div><div><div style={styles.statLabel}>Total Students</div><div style={styles.statNumber}>{totalStudents}</div></div></div>
        <div style={{...styles.statCard, borderLeft: '6px solid #0284c7'}}><div style={styles.statIcon}>🧑‍🏫</div><div><div style={styles.statLabel}>Active Teachers</div><div style={styles.statNumber}>{totalTeachers}</div></div></div>
        <div style={{...styles.statCard, borderLeft: '6px solid #ea580c'}}><div style={styles.statIcon}>📚</div><div><div style={styles.statLabel}>Total Subjects</div><div style={styles.statNumber}>{totalSubjects}</div></div></div>
        <div style={{...styles.statCard, borderLeft: '6px solid #7c3aed'}}><div style={styles.statIcon}>📊</div><div><div style={styles.statLabel}>Quiz Submissions</div><div style={styles.statNumber}>{Array.isArray(results) ? results.length : 0}</div></div></div>
      </div>

      <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifycontent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px', marginBottom: '20px', justifyContent: 'space-between' }}>
          <div>
            <h3 style={{ margin: 0, color: '#1e293b', fontSize: '18px' }}>📝 Academic Performance Evaluation</h3>
          </div>
          
          <div style={{ display: 'flex', gap: '12px', alignItems: 'center' }}>
            <input type="text" placeholder="Search..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.filterInput} />
            <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={styles.filterSelect}>
              <option value="All">All Status</option>
              <option value="Pass">Passed Only</option>
              <option value="Fail">Failed Only</option>
            </select>

            <button onClick={handleDownloadPDF} style={styles.pdfBtn}>📥 Download PDF Report</button>
          </div>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0', backgroundColor: '#f8fafc' }}>
              <th style={styles.th}>No.</th>
              <th style={styles.th}>Student Name</th>
              <th style={styles.th}>Grade</th>
              <th style={styles.th}>Subject</th>
              <th style={styles.th}>Quiz Title</th>
              <th style={styles.th}>Marks</th>
              <th style={styles.th}>Percentage</th>
              <th style={styles.th}>Status</th>
            </tr>
          </thead>
          <tbody>
            {filteredResults.map((r, index) => {
              const percentage = ((r.marks_obtained / r.total_marks) * 100).toFixed(0);
              return (
                <tr key={r.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={styles.td}>{index + 1}</td>
                  <td style={{...styles.td, fontWeight: 'bold'}}>{r.student_name}</td>
                  <td style={styles.td}>{r.grade}</td>
                  <td style={{...styles.td, color: '#0284c7'}}>{r.subject_name}</td>
                  <td style={styles.td}>{r.quiz_title}</td>
                  <td style={styles.td}>{r.marks_obtained} / {r.total_marks}</td>
                  <td style={styles.td}>{percentage}%</td>
                  <td style={styles.td}>
                    <span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '12px', fontWeight: 'bold', backgroundColor: r.status === 'Pass' ? '#dcfce7' : '#fee2e2', color: r.status === 'Pass' ? '#15803d' : '#b91c1c' }}>
                      {r.status}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const styles = {
  statCard: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', display: 'flex', alignItems: 'center', gap: '15px', boxShadow: '0 2px 10px rgba(0,0,0,0.03)' },
  statIcon: { fontSize: '30px', backgroundColor: '#f1f5f9', padding: '10px', borderRadius: '50%' },
  statLabel: { fontSize: '13px', color: '#64748b', fontWeight: 'bold' },
  statNumber: { fontSize: '24px', fontWeight: 'bold', color: '#1e293b', marginTop: '4px' },
  th: { padding: '14px 12px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 12px', fontSize: '14px' },
  filterInput: { padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px' },
  filterSelect: { padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', backgroundColor: 'white' },
  pdfBtn: { padding: '8px 15px', backgroundColor: '#b91c1c', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }
};
